raw:
I will create a dashboard showing revenue by region and month along with a units KPI using your Retail orders dataset. Currently, no specific dataset, visual, or dashboard is open, so per-entity figures are not available. Please open one if you would like to explore the numeric details.
@@ACTION {"kind":"dashboard","intent":"revenue by region and month with a units KPI"}
---
{
  "name": "Revenue and Units Analysis",
  "rationale": "This plan visualizes revenue patterns across regions over time alongside total volume to identify geographic trends. Breaking down monthly performance by region highlights regional growth and seasonal demand.",
  "calculatedFields": [],
  "sheets": [
    {
      "name": "Revenue Overview",
      "metrics": [
        {
          "dataset": "Retail orders",
          "column": "units",
          "aggregation": "sum",
          "label": "Total Units"
        }
      ],
      "visuals": [
        {
          "dataset": "Retail orders",
          "name": "Revenue by Month and Region",
          "chartType": "line",
          "encoding": {
            "category": "Month",
            "values": [
              {
                "column": "revenue",
                "aggregation": "sum"
              }
            ],
            "series": "region"
          },
          "filters": []
        },
        {
          "dataset": "Retail orders",
          "name": "Revenue by Region",
          "chartType": "bar",
          "encoding": {
            "category": "region",
            "values": [
              {
                "column": "revenue",
                "aggregation": "sum"
              }
            ]
          },
          "filters": []
        },
        {
          "visual": "Revenue by month"
        }
      ],
      "texts": [
        {
          "heading": "Overview",
          "text": "This sheet provides visibility into monthly revenue trends segmented by geographic region and tracks overall unit sales volume."
        }
      ]
    }
  ]
}
